CREATE TRIGGER `raw`.trg_building_transactions_no_delete BEFORE DELETE ON `raw`.building_transactions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'raw.building_transactions is write-once (DELETE blocked)';

DROP TRIGGER IF EXISTS `audit`.trg_query_log_no_update;

CREATE TRIGGER `audit`.trg_query_log_no_update BEFORE UPDATE ON `audit`.query_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit.query_log is write-once (UPDATE blocked)';

